    const originalRepair = pendingRepair;
    const failureContext = { requestId: 'integration-repair-failed', projectRoot: root };
    run = await runtime.claim({
      runId: run.runId,
      actionId: originalRepair.id,
      attempt: originalRepair.attempt,
