      expect(recovered?.waits).toEqual(original?.waits);
      expect(recovered?.outputs).toEqual(original?.outputs);
      expect(recovered?.revision).toBe(run.revision + 2);
      const next = await advanceNativeSdkChange(root, run.runId);
