        exitCode: 0,
        data: { phase: 'build', pendingAction: { stepId: 'build.builder' } },
      });
      expectOriginalActionFacts((await store.read(run.runId))!, [failed]);
      expect(await inspectNativeSdkDefinitionUpgrade(root, run.runId, true)).toBeNull();
    },
  );

