      ),
    ).rejects.toThrow('requireIndependentReview must be a boolean');
    run = await runtime.inspect(run.runId);
  }
  const builder = run.actions.at(-1)!;
  if (!builder.claim)
    run = await runtime.claim({
      runId: run.runId,
      actionId: builder.id,
