      readOnly: true,
    });
    const output = {
      candidateCommit: f.candidateCommit,
      verdict: 'pass',
      evidence: {
        summary: 'Reviewed actual API behavior.',
        checks: ['api-check'],
        acceptance: [{ id: 'child:api', result: 'passed', reason: 'The API scenario passed.' }],
      },
