    );
    if (!accepted) {
      await expect(operation).rejects.toThrow(/required independent session/);
      expect((await f.runtime.inspect(f.run.runId)).actions.at(-1)).toMatchObject({
        stepId: 'supervisor.child.verifier',
        status: 'running',
      });
      return;
